def uniform_prob(n_favorable, n_total):
    if n_total == 0:
        raise ValueError('n_total must be > 0')
    return n_favorable / n_total

def conditional(p_a_and_b, p_b):
    if p_b == 0:
        raise ValueError('P(B) must be > 0')
    return p_a_and_b / p_b

